#include "license/license_manager.h"

#include "license/license_crypto.h"
#include "license/machine_id.h"

#include <QCoreApplication>
#include <QDir>
#include <QFile>
#include <QProcessEnvironment>
#include <QStandardPaths>
#include <QTextStream>

// Generated by CMake when BF_REQUIRE_LICENSE=ON. SubjectPublicKeyInfo PEM only;
// never contains a private key. The include defines bf::license_detail::kPublicKeyPem.
#ifdef BF_LICENSE_PUBLIC_KEY_HEADER
#include "bf_license_public_key_embed.h"
#endif

namespace bf {
namespace {

inline QString embeddedPublicKey() {
#ifdef BF_LICENSE_PUBLIC_KEY_HEADER
    return QString::fromLatin1(license_detail::kPublicKeyPem);
#else
    return QString();
#endif
}

QString readRuntimePublicKeyFile(const QString& resourceRoot) {
    QStringList candidates;
    const QString envRoot = QProcessEnvironment::systemEnvironment().value("BF_RESOURCE_ROOT");
    if (!envRoot.isEmpty()) {
        candidates.push_back(QDir(envRoot).filePath("license_public.pem"));
    }
    if (!resourceRoot.isEmpty()) {
        candidates.push_back(QDir(resourceRoot).filePath("license_public.pem"));
    }
    candidates.push_back(QDir(QCoreApplication::applicationDirPath()).filePath("license_public.pem"));
    for (const QString& path : candidates) {
        QFile file(path);
        if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
            const QString pem = QString::fromUtf8(file.readAll()).trimmed();
            if (pem.contains("BEGIN PUBLIC KEY")) {
                return pem;
            }
        }
    }
    return QString();
}

QString licenseDataDir() {
#ifdef Q_OS_WIN
    const QString appData = QProcessEnvironment::systemEnvironment().value("APPDATA");
    if (!appData.isEmpty()) {
        return QDir(appData).filePath("BoundFreeEEG");
    }
    return QDir(QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)).filePath("BoundFreeEEG");
#else
    QString base = QProcessEnvironment::systemEnvironment().value("XDG_DATA_HOME");
    if (base.isEmpty()) {
        base = QDir::homePath() + "/.local/share";
    }
    return QDir(base).filePath("boundfree-eeg");
#endif
}

}  // namespace

LicenseManager::LicenseManager(QString productVersion, QString resourceRoot)
    : productVersion_(std::move(productVersion))
    , resourceRoot_(std::move(resourceRoot))
    , publicKeyPem_(resolvePublicKeyPem()) {}

QString LicenseManager::resolvePublicKeyPem() const {
    // Embed wins (release build), then runtime file, else empty (dev default).
    const QString embedded = embeddedPublicKey();
    if (!embedded.isEmpty() && embedded.contains("BEGIN PUBLIC KEY")) {
        return embedded;
    }
    return readRuntimePublicKeyFile(resourceRoot_);
}

bool LicenseManager::isBackendAvailable() const {
    return license_crypto::isBackendAvailable();
}

const QString& LicenseManager::publicKeyPem() const {
    return publicKeyPem_;
}

bool LicenseManager::isConfigured() const {
    return !publicKeyPem_.isEmpty();
}

QString LicenseManager::resolveLocalMachineIdCanonical() const {
    return machineIdCanonical(readMachineGuid());
}

QString LicenseManager::licenseFilePath() const {
    return QDir(licenseDataDir()).filePath("license.dat");
}

QString LicenseManager::loadSavedLicense() const {
    QFile file(licenseFilePath());
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        return QString();
    }
    return QString::fromUtf8(file.readAll()).trimmed();
}

bool LicenseManager::saveLicense(const QString& licenseKey) const {
    const QString dir = licenseDataDir();
    QDir().mkpath(dir);
    QFile file(licenseFilePath());
    if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text)) {
        return false;
    }
    QTextStream out(&file);
    out << licenseKey.trimmed();
    out.flush();
    return file.flush();
}

LicenseResult LicenseManager::verifyKey(const QString& licenseKey) const {
    return verifyKey(licenseKey, resolveLocalMachineIdCanonical(), QString());
}

LicenseResult LicenseManager::verifyKey(const QString& licenseKey,
                                         const QString& localMachineIdCanonical,
                                         const QString& todayIso) const {
    return verifyLicenseKey(licenseKey, publicKeyPem_, localMachineIdCanonical,
                           productVersion_, todayIso);
}

LicenseResult LicenseManager::checkSavedLicense() const {
    const QString key = loadSavedLicense();
    if (key.isEmpty()) {
        LicenseResult result;
        result.status = LicenseStatus::Missing;
        result.error = makeError("license.missing", {{"path", licenseFilePath()}});
        return result;
    }
    return verifyKey(key);
}

}  // namespace bf
